package com.dunerealms.staff;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.sql.*;import java.math.*;import java.util.*;import java.util.concurrent.atomic.*;
class CaseStoreTest {
 UUID actor=UUID.randomUUID(),target=UUID.fromString("00000000-0000-0000-0009-01f09764757f"),creator=UUID.randomUUID();String url;AtomicReference<CaseStore.Grant> grant;AtomicBoolean bank;CaseStore store;
 @BeforeEach void setup()throws Exception{
  url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";
  grant=new AtomicReference<>(new CaseStore.Grant(229211,3,actor,creator,target,target,true,true,true,true));bank=new AtomicBoolean(true);store=new CaseStore((c,a,t,v,x)->grant.get(),(c,a,credit)->bank.get());
  try(Connection c=open();Statement q=c.createStatement()){
   CaseStore.initialize(c);q.execute("CREATE TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL)");q.execute("CREATE TABLE dune_staff_bank_wallet(account_key VARCHAR(16) PRIMARY KEY,balance DECIMAL(20,2),updated_at BIGINT)");q.execute("CREATE TABLE dune_staff_bank_ledger(id VARCHAR(36) PRIMARY KEY,player_uuid VARCHAR(36),action VARCHAR(32),delta DECIMAL(20,2),balance_after DECIMAL(20,2),created_at BIGINT,reference VARCHAR(100) UNIQUE)");q.execute("INSERT INTO dune_staff_bank_wallet VALUES('network',500,0)");
   try(PreparedStatement p=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,100)")){p.setString(1,target.toString());p.executeUpdate();}
  }
 }
 Connection open()throws SQLException{return DriverManager.getConnection(url);}BigDecimal n(String s){return new BigDecimal(s);}
 BigDecimal balance(Connection c,boolean treasury)throws Exception{try(PreparedStatement q=c.prepareStatement(treasury?"SELECT balance FROM dune_staff_bank_wallet":"SELECT balance FROM dune_economy_balances WHERE uuid=?")){if(!treasury)q.setString(1,target.toString());try(ResultSet r=q.executeQuery()){r.next();return r.getBigDecimal(1);}}}
 int count(Connection c,String table)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getInt(1);}}
 void correct(Connection c,UUID id,String amount,boolean credit)throws SQLException{store.correction(c,id,actor,229211,3,target,n(amount),credit);}
 @Test void canonicalFactionChangeRecordsDetailAndRollsBackWithTargetCheckpoint()throws Exception{
  grant.set(new CaseStore.Grant(229211,3,actor,creator,target,target,true,true,true,true,true));UUID receipt=UUID.randomUUID();
  try(Connection c=open()){c.setAutoCommit(false);store.factionChange(c,receipt,actor,229211,3,target,"Atreides");try(PreparedStatement q=c.prepareStatement("SELECT action,details FROM dune_staff_case_audit WHERE id=?")){q.setString(1,receipt.toString());try(ResultSet r=q.executeQuery()){assertTrue(r.next());assertEquals("edit_faction",r.getString(1));assertEquals("Faction assignment: Atreides",r.getString(2));}}c.rollback();assertEquals(0,count(c,"dune_staff_case_audit"));store.factionChange(c,receipt,actor,229211,3,target,"Atreides");c.commit();assertThrows(SQLException.class,()->store.factionChange(c,receipt,actor,229211,3,target,"Atreides"));c.rollback();assertEquals(1,count(c,"dune_staff_case_audit"));assertEquals(n("100.00"),balance(c,false));assertEquals(n("500.00"),balance(c,true));}
 }
 @Test void ungrantedFactionActionAndNoncanonicalFactionOrSelfTargetReject()throws Exception{
  try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->store.factionChange(c,UUID.randomUUID(),actor,229211,3,target,"Atreides"));grant.set(new CaseStore.Grant(229211,3,actor,creator,target,target,true,true,true,true,true));for(String bad:List.of("atreides","Aedrecht","Atreides;op","Guild"))assertThrows(SQLException.class,()->store.factionChange(c,UUID.randomUUID(),actor,229211,3,target,bad));assertThrows(SQLException.class,()->store.factionChange(c,UUID.randomUUID(),actor,229211,3,actor,"Atreides"));assertEquals(0,count(c,"dune_staff_case_audit"));}
 }
 @Test void existingAuditTableGetsOnlyIdempotentDetailColumnMigration()throws Exception{
  try(Connection c=open();Statement q=c.createStatement()){q.execute("ALTER TABLE dune_staff_case_audit DROP COLUMN details");CaseStore.initialize(c);CaseStore.initialize(c);try(ResultSet r=c.getMetaData().getColumns(c.getCatalog(),null,"dune_staff_case_audit","details")){assertTrue(r.next());}}
 }
 @Test void balancePreviewRequiresCurrentCaseAndBankAuthorityButDoesNotMoveFunds()throws Exception{try(Connection c=open()){c.setAutoCommit(false);var view=store.balances(c,actor,229211,3,target,true);assertEquals(n("100.00"),view.wallet());assertEquals(n("500.00"),view.treasury());assertEquals(0,count(c,"dune_staff_case_audit"));bank.set(false);assertThrows(SQLException.class,()->store.balances(c,actor,229211,3,target,true));c.rollback();}}
 @Test void creditsAndRecoveriesConserveCentsAndProduceMatchingAuditAndBankLedger()throws Exception{try(Connection c=open()){c.setAutoCommit(false);correct(c,UUID.randomUUID(),"10.25",false);c.commit();assertEquals(n("89.75"),balance(c,false));assertEquals(n("510.25"),balance(c,true));correct(c,UUID.randomUUID(),"20.05",true);c.commit();assertEquals(n("109.80"),balance(c,false));assertEquals(n("490.20"),balance(c,true));assertEquals(n("600.00"),balance(c,false).add(balance(c,true)));assertEquals(2,count(c,"dune_staff_case_audit"));assertEquals(2,count(c,"dune_staff_bank_ledger"));}}
 @Test void duplicateConfirmationCannotDebitOrCreditTwice()throws Exception{UUID id=UUID.randomUUID();try(Connection c=open()){c.setAutoCommit(false);correct(c,id,"10",true);c.commit();assertThrows(SQLException.class,()->correct(c,id,"10",true));c.rollback();assertEquals(n("110.00"),balance(c,false));assertEquals(n("490.00"),balance(c,true));assertEquals(1,count(c,"dune_staff_case_audit"));}}
 @Test void rollbackRestoresBothBalancesAndDurableReceipts()throws Exception{try(Connection c=open()){c.setAutoCommit(false);correct(c,UUID.randomUUID(),"50",true);c.rollback();assertEquals(n("100.00"),balance(c,false));assertEquals(n("500.00"),balance(c,true));assertEquals(0,count(c,"dune_staff_case_audit"));assertEquals(0,count(c,"dune_staff_bank_ledger"));}}
 @Test void underfundedWalletOrTreasuryNeverMintsMoney()throws Exception{try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"100.01",false));c.rollback();assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"500.01",true));c.rollback();assertEquals(n("600.00"),balance(c,false).add(balance(c,true)));assertEquals(0,count(c,"dune_staff_case_audit"));}}
 @Test void invalidAmountsAndUnfencedWritesFailBeforeAnyMutation()throws Exception{try(Connection c=open()){assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"1",true));c.setAutoCommit(false);for(String amount:List.of("0","-1","0.001","1000000.01"))assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),amount,true));assertEquals(0,count(c,"dune_staff_case_audit"));}}
 @Test void currentBankAuthorityIsIndependentOfCaseAssignment()throws Exception{bank.set(false);try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"1",true));assertEquals(0,count(c,"dune_staff_case_audit"));}}
 @Test void staleVersionChangedAssignmentOrDifferentSubjectRejects()throws Exception{
  for(CaseStore.Grant stale:List.of(new CaseStore.Grant(229211,4,actor,creator,target,target,true,true,true,true),new CaseStore.Grant(229211,3,UUID.randomUUID(),creator,target,target,true,true,true,true),new CaseStore.Grant(229211,3,actor,creator,UUID.randomUUID(),target,true,true,true,true))){grant.set(stale);try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"1",true));assertEquals(0,count(c,"dune_staff_case_audit"));}}
 }
 @Test void revokedActionFlagsAndSelfCorrectionDeny()throws Exception{grant.set(new CaseStore.Grant(229211,3,actor,creator,target,target,true,true,false,false));try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->correct(c,UUID.randomUUID(),"1",true));assertThrows(SQLException.class,()->store.confiscation(c,UUID.randomUUID(),actor,229211,3,target,0,new byte[]{1}));assertThrows(SQLException.class,()->store.correction(c,UUID.randomUUID(),actor,229211,3,actor,n("1"),true));}}
 @Test void exactItemEvidenceIsDurableAndRollsBackWithCheckpoint()throws Exception{byte[] evidence={0,1,2,(byte)255};UUID id=UUID.randomUUID();try(Connection c=open()){c.setAutoCommit(false);store.confiscation(c,id,actor,229211,3,target,40,evidence);try(PreparedStatement q=c.prepareStatement("SELECT item_bytes,slot_index FROM dune_staff_case_audit WHERE id=?")){q.setString(1,id.toString());try(ResultSet r=q.executeQuery()){r.next();assertArrayEquals(evidence,r.getBytes(1));assertEquals(40,r.getInt(2));}}c.rollback();assertEquals(0,count(c,"dune_staff_case_audit"));store.confiscation(c,id,actor,229211,3,target,40,evidence);c.commit();assertThrows(SQLException.class,()->store.confiscation(c,id,actor,229211,3,target,40,evidence));c.rollback();assertEquals(1,count(c,"dune_staff_case_audit"));}}
 @Test void boundedSlotAndSerializedEvidenceRequired()throws Exception{try(Connection c=open()){c.setAutoCommit(false);for(int slot:List.of(-1,41))assertThrows(SQLException.class,()->store.confiscation(c,UUID.randomUUID(),actor,229211,3,target,slot,new byte[]{1}));for(byte[] evidence:Arrays.asList(null,new byte[0],new byte[1024*1024+1]))assertThrows(SQLException.class,()->store.confiscation(c,UUID.randomUUID(),actor,229211,3,target,0,evidence));assertEquals(0,count(c,"dune_staff_case_audit"));}}
 @Test void canonicalBedrockUuidAcceptedWithoutJavaOfflineHashing()throws Exception{assertEquals(target,CaseStore.identity(target.toString()));for(String bad:List.of("00000000-0000-0000-0000-000000000000",".unimatrix999780",target.toString().toUpperCase()))assertThrows(SQLException.class,()->CaseStore.identity(bad));}
 @Test void sqlAuthorityResultMustMatchActorTicketVersionAndSingleRow()throws Exception{
  Connection c=mock(Connection.class);CallableStatement q=mock(CallableStatement.class);ResultSet r=mock(ResultSet.class);when(c.getAutoCommit()).thenReturn(false);when(c.prepareCall(anyString())).thenReturn(q);when(q.execute()).thenReturn(true);when(q.getResultSet()).thenReturn(r);when(r.next()).thenReturn(true,false);when(r.getString("actor_uuid")).thenReturn(UUID.randomUUID().toString());assertThrows(SQLException.class,()->CaseStore.lockedGrant(c,actor,229211,3,CaseStore.Action.inspect_inventory));verify(q).setString(1,actor.toString());verify(q).setLong(2,229211);verify(q).setLong(3,3);verify(q).setString(4,"inspect_inventory");
 }
}


